-- Parent self-service membership requests feed URWS without exposing service-role access or storing medical detail in standard evidence.
insert into public.urws_case_types(code,name,domain,description,sensitivity,default_owner_role) values
('membership_cancellation_request','Membership Cancellation Request','membership','Parent or guardian requested a membership cancellation requiring policy-aware review.','standard','admin'),
('membership_billing_review','Membership Billing Review','membership','Parent or guardian requested review of membership billing without an automatic refund promise.','standard','finance')
on conflict (code) do update set name=excluded.name,domain=excluded.domain,description=excluded.description,sensitivity=excluded.sensitivity,default_owner_role=excluded.default_owner_role,active=true;
create or replace function public.parent_get_family_os(p_family_id uuid) returns jsonb language plpgsql security definer set search_path=public,app as $$ begin if p_family_id is null or not app.can_access_family(p_family_id) then raise exception 'Family access denied' using errcode='42501';end if;return public.get_parent_hub(p_family_id);end $$; grant execute on function public.parent_get_family_os(uuid) to authenticated;
create or replace function public.parent_membership_options(p_family_id uuid) returns jsonb language plpgsql security definer set search_path=public,app as $$ declare v jsonb;begin if p_family_id is null or not app.can_access_family(p_family_id) then raise exception 'Family access denied' using errcode='42501';end if;select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'organization_id',m.organization_id,'organization_name',o.name,'person_id',m.person_id,'membership_number',m.membership_number,'membership_type',m.membership_type,'status',m.status,'starts_on',m.starts_on,'ends_on',m.ends_on,'athlete_name',trim(concat(coalesce(p.preferred_name,p.first_name,''),' ',coalesce(p.last_name,'')))) order by p.last_name,p.first_name),'[]'::jsonb) into v from public.memberships m join public.people p on p.id=m.person_id join public.organizations o on o.id=m.organization_id where m.person_id in(select fm.person_id from public.family_members fm where fm.family_id=p_family_id union select a.person_id from public.athletes a where a.primary_family_id=p_family_id);return v;end $$;grant execute on function public.parent_membership_options(uuid) to authenticated;
create or replace function public.parent_submit_membership_request(p_family_id uuid,p_membership_id uuid,p_request_kind text,p_parent_summary text,p_amount numeric default null,p_requested_start_on date default null,p_requested_end_on date default null,p_acknowledged boolean default false,p_acknowledgement_text text default null) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare m public.memberships%rowtype;o public.organizations%rowtype;v_person uuid;v_case uuid;v_source uuid;v_case_type text;v_public_summary text;v_tenant uuid;v_event text;
begin
 if p_family_id is null or not app.can_access_family(p_family_id) then raise exception 'Family access denied' using errcode='42501';end if;if p_request_kind not in ('pause','medical_absence','cancel','refund_review','billing_review') then raise exception 'Unsupported membership request';end if;if not p_acknowledged or length(trim(coalesce(p_acknowledgement_text,'')))<8 then raise exception 'Acknowledgement of displayed consequences is required';end if;v_person:=app.current_person_id();if v_person is null then raise exception 'Parent request requires a person identity';end if;select * into m from public.memberships where id=p_membership_id;if not found then raise exception 'Membership not found';end if;if not exists(select 1 from public.family_members fm where fm.family_id=p_family_id and fm.person_id=m.person_id union select 1 from public.athletes a where a.primary_family_id=p_family_id and a.person_id=m.person_id) then raise exception 'Membership is not connected to this family' using errcode='42501';end if;select * into o from public.organizations where id=m.organization_id;v_tenant:=o.tenant_id;v_case_type:=case p_request_kind when 'refund_review' then 'membership_refund_dispute' when 'billing_review' then 'membership_billing_review' when 'cancel' then 'membership_cancellation_request' else 'membership_pause_exception' end;v_public_summary:=case when p_request_kind='medical_absence' then 'Parent requested a medical absence/pause. Restricted health details are not stored in the standard URWS record.' else coalesce(nullif(trim(p_parent_summary),''),'Parent submitted a membership request for review.') end;
 if p_request_kind in ('pause','medical_absence') then insert into public.membership_exceptions(organization_id,membership_id,exception_type,reason_category,requested_start_on,requested_end_on,status,requested_by_person_id,restricted_details) values(m.organization_id,m.id,case when p_request_kind='medical_absence' then 'medical_pause' else 'pause' end,case when p_request_kind='medical_absence' then 'medical_absence' else 'parent_request' end,p_requested_start_on,p_requested_end_on,'requested',v_person,'{}'::jsonb) returning id into v_source;v_event:='membership.pause.requested';elsif p_request_kind='refund_review' then if p_amount is null or p_amount<0 then raise exception 'Refund review amount must be zero or greater';end if;insert into public.refund_requests(organization_id,membership_id,requested_by_person_id,amount,currency,reason,status,policy_eligibility) values(m.organization_id,m.id,v_person,p_amount,'CAD',nullif(trim(p_parent_summary),''),'requested','unassessed') returning id into v_source;v_event:='membership.refund.requested';elsif p_request_kind='cancel' then insert into public.membership_lifecycle_events(organization_id,membership_id,event_type,effective_at,actor_person_id,source_type,summary,evidence) values(m.organization_id,m.id,'cancellation_requested',now(),v_person,'parent_portal','Parent requested membership cancellation.',jsonb_build_object('acknowledged',true)) returning id into v_source;v_event:='membership.cancellation.requested';else v_event:='membership.billing_review.requested';end if;
 insert into public.urws_cases(tenant_id,organization_id,case_type_code,subject_type,subject_id,opened_by_person_id,status,priority,public_summary,financial_impact,currency,origin_key,metadata) values(v_tenant,m.organization_id,v_case_type,'membership',m.id,v_person,'open',case when p_request_kind in ('refund_review','billing_review') then 'high' else 'normal' end,v_public_summary,case when p_request_kind='refund_review' then p_amount else null end,'CAD','parent-request:'||p_request_kind||':'||coalesce(v_source::text,gen_random_uuid()::text),jsonb_build_object('family_id',p_family_id,'request_kind',p_request_kind,'source_id',v_source)) returning id into v_case;insert into public.urws_case_links(case_id,linked_type,linked_id,relationship) values(v_case,'membership',m.id,'primary_subject') on conflict do nothing;if v_source is not null then insert into public.urws_case_links(case_id,linked_type,linked_id,relationship) values(v_case,case when p_request_kind='refund_review' then 'refund_request' when p_request_kind in ('pause','medical_absence') then 'membership_exception' else 'membership_lifecycle_event' end,v_source,'request_source') on conflict do nothing;end if;
 insert into public.urws_evidence_items(tenant_id,organization_id,case_id,evidence_type,source_type,source_id,occurred_at,recorded_by_person_id,sensitivity,summary,facts) values(v_tenant,m.organization_id,v_case,'parent_acknowledgement','parent_portal',v_source,now(),v_person,'standard','Parent acknowledged displayed membership consequences before submitting the request.',jsonb_build_object('request_kind',p_request_kind,'acknowledgement_text',trim(p_acknowledgement_text),'requested_start_on',p_requested_start_on,'requested_end_on',p_requested_end_on));insert into public.urws_expected_transitions(tenant_id,organization_id,subject_type,subject_id,expectation_key,expected_event_type,due_at,grace_until,status,escalation_policy) values(v_tenant,m.organization_id,'urws_case',v_case,'parent_membership_request_review','urws.case.decided',now()+interval '3 days',now()+interval '4 days','pending',jsonb_build_object('escalate_to','org_admin','source','parent_portal'));insert into public.platform_event_outbox(tenant_id,event_type,aggregate_type,aggregate_id,actor_person_id,payload) values(v_tenant,'parent.membership.request.submitted','urws_case',v_case,v_person,jsonb_build_object('organization_id',m.organization_id,'membership_id',m.id,'request_kind',p_request_kind,'domain_event',v_event));return jsonb_build_object('case_id',v_case,'source_id',v_source,'request_kind',p_request_kind,'status','submitted');
end $$;
grant execute on function public.parent_submit_membership_request(uuid,uuid,text,text,numeric,date,date,boolean,text) to authenticated;
